// Remove matching rows or columns of tiles, then let the remaining tiles fall down.
// match-grid: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,minimum_run,...tiles]
// Output: [matched_count,...collapsed_tiles]
// Tile -1 is empty. Detect horizontal/vertical matches, merge intersections, then apply column
// gravity. No random refill or cascade.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

// Count how many numbers are in this list.
function port_length(a: number[]): number { return a.length; }
// Read one number at a zero-based position; stop if that position does not exist.
function port_get(a: number[], i: number): number { if (!Number.isInteger(i) || i < 0 || i >= a.length) throw new RangeError("index"); return a[i]; }
// Replace a number at an existing position in the list.
function port_put(a: number[], i: number, v: number): void { port_get(a,i); a[i]=v; }
// Add one number to the end of the list.
function port_push(a: number[], v: number): void { a.push(v); }

// 1. Find long enough runs of identical nonempty tiles.
// 2. Mark each matching tile once, even where a row and column cross.
// 3. Remove all marked tiles together.
// 4. Slide surviving tiles to the bottom of each column without changing their order.
export function compute(data: number[]): number[] {
    let w: number = 0;
    let h: number = 0;
    let minimum_run: number = 0;
    let matched: number[] = [];
    let i: number = 0;
    let axis: number = 0;
    let count: number = 0;
    let grid: number[] = [];
    let x: number = 0;
    let result: number[] = [];
    let lines: number = 0;
    let span: number = 0;
    let line: number = 0;
    let bottom: number = 0;
    let y: number = 0;
    let start: number = 0;
    let cell: number = 0;
    let stride: number = 0;
    let tile: number = 0;
    let end_index: number = 0;
    let j: number = 0;
    w = port_get(data, 0);
    h = port_get(data, 1);
    minimum_run = port_get(data, 2);
    if (((w < 1) || (h < 1) || (minimum_run < 2) || (port_length(data) != (3 + (w * h))))) {
        return [-(1)];
    }
    matched = [];
    i = 0;
    while ((i < (w * h))) {
        port_push(matched, 0);
        i += 1;
    }
    axis = 0;
    while ((axis < 2)) {
        lines = h;
        span = w;
        if ((axis == 1)) {
            lines = w;
            span = h;
        }
        line = 0;
        while ((line < lines)) {
            start = 0;
            while ((start < span)) {
                cell = ((line * w) + start);
                stride = 1;
                if ((axis == 1)) {
                    cell = ((start * w) + line);
                    stride = w;
                }
                tile = port_get(data, (3 + cell));
                end_index = (start + 1);
                while (((end_index < span) && (port_get(data, ((3 + cell) + ((end_index - start) * stride))) == tile))) {
                    end_index += 1;
                }
                if (((tile != -(1)) && ((end_index - start) >= minimum_run))) {
                    j = start;
                    while ((j < end_index)) {
                        port_put(matched, (cell + ((j - start) * stride)), 1);
                        j += 1;
                    }
                }
                start = end_index;
            }
            line += 1;
        }
        axis += 1;
    }
    count = 0;
    grid = [];
    i = 0;
    while ((i < (w * h))) {
        count += port_get(matched, i);
        port_push(grid, -(1));
        i += 1;
    }
    x = 0;
    while ((x < w)) {
        bottom = (h - 1);
        y = (h - 1);
        while ((y >= 0)) {
            cell = ((y * w) + x);
            if (((port_get(matched, cell) == 0) && (port_get(data, (3 + cell)) != -(1)))) {
                port_put(grid, ((bottom * w) + x), port_get(data, (3 + cell)));
                bottom -= 1;
            }
            y -= 1;
        }
        x += 1;
    }
    result = [count];
    i = 0;
    while ((i < port_length(grid))) {
        port_push(result, port_get(grid, i));
        i += 1;
    }
    return result;
}
